import { getMetaContent } from "helpers/meta_helpers"

const MILLISECONDS_IN_A_DAY = 1000 * 60 * 60 * 24
const DAYS_IN_A_WEEK = 7

// Turn a timestamp into words in the viewer's own timezone: today reads as a
// clock time ("1:42 PM"), the days around it read as "yesterday" or "in 3
// days", and anything further out reads as a date ("Sep 12").
export function formatDate(date, format = "relative", now = new Date()) {
  return (FORMATS[format] || FORMATS.relative)(date, now)
}

export function formatFullDate(date) {
  return dateFormatterFor({ dateStyle: "full", timeStyle: "short" }).format(date)
}

export function signedDifferenceInDays(fromDate, toDate) {
  return Math.round((beginningOfDay(toDate) - beginningOfDay(fromDate)) / MILLISECONDS_IN_A_DAY)
}

export function beginningOfDay(date) {
  const { year, month, day } = datePartsInTimezone(date)
  return new Date(Date.UTC(year, month - 1, day))
}

const FORMATS = {
  relative: relativeDate,          // "1:42 PM", "yesterday", "5 days ago", "in 3 days", "Sep 12"
  time: timeOfDay,                 // "1:42 PM"
  date: shortDate,                 // "Sep 12", "Sep 12, 2024" in other years
  date_with_year: dateWithYear,    // "Sep 12, 2025"
  weekday: weekday,                // "Friday, September 12"
  date_and_time: dateAndTime       // "9/12/25, 1:42 PM"
}

function relativeDate(date, now) {
  const days = signedDifferenceInLocalDays(now, date)

  if (days === 0) {
    return timeOfDay(date)
  } else if (Math.abs(days) < DAYS_IN_A_WEEK) {
    return relativeDays(days)
  } else {
    return shortDate(date, now)
  }
}

function relativeDays(days) {
  return relativeDateFormatter().format(days, "day")
}

function timeOfDay(date) {
  return dateFormatterFor({ hour: "numeric", minute: "2-digit" }).format(date)
}

function shortDate(date, now = new Date()) {
  return date.getFullYear() === now.getFullYear() ?
    dateFormatterFor({ month: "short", day: "numeric" }).format(date) :
    dateWithYear(date)
}

function dateWithYear(date) {
  return dateFormatterFor({ month: "short", day: "numeric", year: "numeric" }).format(date)
