  get #time() {
    const datetime = this.element.getAttribute("datetime")
    const time = datetime ? new Date(datetime) : null

    return isNaN(time) ? null : time
  }
}

// Relative times go stale as the clock ticks, so refresh them all from one timer.
const rendering = new Set()
let timer

function startRefreshing(controller) {
  rendering.add(controller)
  timer ||= setInterval(refreshAll, REFRESH_INTERVAL)
}

function stopRefreshing(controller) {
  rendering.delete(controller)

  if (rendering.size === 0) {
    clearInterval(timer)
    timer = null
  }
}

function refreshAll() {
  rendering.forEach(controller => controller.render())
}
